        /**
         * The text.
         */
        val `value`: kotlin.String) : AnswerValue()
        
    {
        

        companion object
    }
    
    /**
     * A toggle.
     */
    data class Bool(
        /**
         * On or off.
         */
        val `value`: kotlin.Boolean) : AnswerValue()
        
    {
        

        companion object
    }
    
    /**
     * A slider position.
     */
    data class Number(
        /**
         * The number.
         */
        val `value`: kotlin.Double) : AnswerValue()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAnswerValue : FfiConverterRustBuffer<AnswerValue>{
    override fun read(buf: ByteBuffer): AnswerValue {
        return when(buf.getInt()) {
            1 -> AnswerValue.Text(
                FfiConverterString.read(buf),
                )
            2 -> AnswerValue.Bool(
                FfiConverterBoolean.read(buf),
                )
            3 -> AnswerValue.Number(
                FfiConverterDouble.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: AnswerValue): ULong = when(value) {
        is AnswerValue.Text -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`value`)
            )
        }
        is AnswerValue.Bool -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterBoolean.allocationSize(value.`value`)
            )
        }
        is AnswerValue.Number -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterDouble.allocationSize(value.`value`)
            )
        }
    }

    override fun write(value: AnswerValue, buf: ByteBuffer) {
        when(value) {
            is AnswerValue.Text -> {
                buf.putInt(1)
                FfiConverterString.write(value.`value`, buf)
                Unit
            }
            is AnswerValue.Bool -> {
                buf.putInt(2)
                FfiConverterBoolean.write(value.`value`, buf)
                Unit
            }
            is AnswerValue.Number -> {
                buf.putInt(3)
                FfiConverterDouble.write(value.`value`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





