                )
            3 -> FieldKind.Toggle
            4 -> FieldKind.Slider(
                FfiConverterDouble.read(buf),
                FfiConverterDouble.read(buf),
                FfiConverterDouble.read(buf),
                FfiConverterMapStringString.read(buf),
                FfiConverterOptionalDouble.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FieldKind): ULong = when(value) {
        is FieldKind.Text -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterOptionalTypeTextFormat.allocationSize(value.`format`)
                + FfiConverterOptionalString.allocationSize(value.`autocomplete`)
            )
        }
        is FieldKind.Choice -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceTypeChoiceOption.allocationSize(value.`options`)
            )
        }
        is FieldKind.Toggle -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FieldKind.Slider -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterDouble.allocationSize(value.`min`)
                + FfiConverterDouble.allocationSize(value.`max`)
                + FfiConverterDouble.allocationSize(value.`step`)
                + FfiConverterMapStringString.allocationSize(value.`valueLabels`)
                + FfiConverterOptionalDouble.allocationSize(value.`defaultValue`)
            )
        }
    }

    override fun write(value: FieldKind, buf: ByteBuffer) {
        when(value) {
            is FieldKind.Text -> {
                buf.putInt(1)
                FfiConverterOptionalTypeTextFormat.write(value.`format`, buf)
                FfiConverterOptionalString.write(value.`autocomplete`, buf)
                Unit
            }
            is FieldKind.Choice -> {
                buf.putInt(2)
                FfiConverterSequenceTypeChoiceOption.write(value.`options`, buf)
                Unit
            }
            is FieldKind.Toggle -> {
                buf.putInt(3)
                Unit
            }
            is FieldKind.Slider -> {
                buf.putInt(4)
                FfiConverterDouble.write(value.`min`, buf)
                FfiConverterDouble.write(value.`max`, buf)
                FfiConverterDouble.write(value.`step`, buf)
                FfiConverterMapStringString.write(value.`valueLabels`, buf)
                FfiConverterOptionalDouble.write(value.`defaultValue`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







/**
 * Errors surfaced to Swift and Kotlin.
 */
sealed class KineticException: kotlin.Exception() {
    
    /**
     * The form schema JSON was rejected; `reason` says why.
     */
    class InvalidSchema(
        
        /**
         * Human-readable reason, the same text the TypeScript core throws.
         * Not called `message`: that clashes with `Throwable.message` in the generated Kotlin.
         */
        val `reason`: kotlin.String
        ) : KineticException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * An action named a field the schema does not have.
     */
    class UnknownField(
        
        /**
         * The offending id.
         */
        val `id`: kotlin.String
        ) : KineticException() {
        override val message
            get() = "id=${ `id` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<KineticException> {
        override fun lift(error_buf: RustBuffer.ByValue): KineticException = FfiConverterTypeKineticError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeKineticError : FfiConverterRustBuffer<KineticException> {
    override fun read(buf: ByteBuffer): KineticException {
        

        return when(buf.getInt()) {
            1 -> KineticException.InvalidSchema(
                FfiConverterString.read(buf),
                )
            2 -> KineticException.UnknownField(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: KineticException): ULong {
        return when(value) {
            is KineticException.InvalidSchema -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is KineticException.UnknownField -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`id`)
            )
        }
    }

    override fun write(value: KineticException, buf: ByteBuffer) {
        when(value) {
            is KineticException.InvalidSchema -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is KineticException.UnknownField -> {
                buf.putInt(2)
                FfiConverterString.write(value.`id`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



