/**
 * One sensor reading; `t` is milliseconds on the app's monotonic clock.
 */
sealed class Sample {
    
    /**
     * Raw acceleration in m/s^2 including gravity.
     */
    data class Acceleration(
        /**
         * Timestamp in ms.
         */
        val `t`: kotlin.Double, 
        /**
         * X axis.
         */
        val `x`: kotlin.Double, 
        /**
         * Y axis.
         */
        val `y`: kotlin.Double, 
        /**
         * Z axis.
         */
        val `z`: kotlin.Double) : Sample()
        
    {
        

        companion object
    }
    
    /**
     * An explicit state (bypasses hysteresis).
     */
    data class State(
        /**
         * Timestamp in ms.
         */
        val `t`: kotlin.Double, 
        /**
         * The state.
         */
        val `state`: uniffi.kinetic.MotionState) : Sample()
        
    {
        

        companion object
    }
    
    /**
     * An OS activity classification.
     */
    data class Activity(
        /**
         * Timestamp in ms.
         */
        val `t`: kotlin.Double, 
        /**
         * The activity.
         */
        val `activity`: uniffi.kinetic.ActivityKind, 
        /**
         * Confidence 0..1.
         */
        val `confidence`: kotlin.Double) : Sample()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeSample : FfiConverterRustBuffer<Sample>{
    override fun read(buf: ByteBuffer): Sample {
        return when(buf.getInt()) {
            1 -> Sample.Acceleration(
                FfiConverterDouble.read(buf),
                FfiConverterDouble.read(buf),
                FfiConverterDouble.read(buf),
                FfiConverterDouble.read(buf),
                )
            2 -> Sample.State(
                FfiConverterDouble.read(buf),
                FfiConverterTypeMotionState.read(buf),
                )
            3 -> Sample.Activity(
                FfiConverterDouble.read(buf),
                FfiConverterTypeActivityKind.read(buf),
                FfiConverterDouble.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Sample): ULong = when(value) {
        is Sample.Acceleration -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterDouble.allocationSize(value.`t`)
                + FfiConverterDouble.allocationSize(value.`x`)
                + FfiConverterDouble.allocationSize(value.`y`)
                + FfiConverterDouble.allocationSize(value.`z`)
            )
        }
        is Sample.State -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterDouble.allocationSize(value.`t`)
                + FfiConverterTypeMotionState.allocationSize(value.`state`)
            )
        }
        is Sample.Activity -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterDouble.allocationSize(value.`t`)
                + FfiConverterTypeActivityKind.allocationSize(value.`activity`)
                + FfiConverterDouble.allocationSize(value.`confidence`)
            )
        }
    }

    override fun write(value: Sample, buf: ByteBuffer) {
        when(value) {
            is Sample.Acceleration -> {
                buf.putInt(1)
                FfiConverterDouble.write(value.`t`, buf)
                FfiConverterDouble.write(value.`x`, buf)
                FfiConverterDouble.write(value.`y`, buf)
                FfiConverterDouble.write(value.`z`, buf)
                Unit
            }
            is Sample.State -> {
                buf.putInt(2)
                FfiConverterDouble.write(value.`t`, buf)
                FfiConverterTypeMotionState.write(value.`state`, buf)
                Unit
            }
            is Sample.Activity -> {
                buf.putInt(3)
                FfiConverterDouble.write(value.`t`, buf)
                FfiConverterTypeActivityKind.write(value.`activity`, buf)
                FfiConverterDouble.write(value.`confidence`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
